import { createReadStream } from 'node:fs';
import { chmod, copyFile, mkdir, rename, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { Readable } from 'node:stream';
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { config } from '../config.js';

/**
 * Where uploaded documents live. Keys are generated by the server (never taken from user input). Files go in and out as
 * streams, so a document is never held in memory whole.
 */
export interface Storage {
  /** Stores a small in-memory file (seed data, generated documents). */
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Moves a validated temporary upload into storage. */
  putFile(key: string, file: string, contentType: string, size: number): Promise<void>;
  stream(key: string): Promise<Readable>;
  remove(key: string): Promise<void>;
}

// Owner-only permissions (ignored on Windows, where the directory's ACL applies).
const DIR_MODE = 0o700, FILE_MODE = 0o600;

class LocalStorage implements Storage {
  private root = path.resolve(config.STORAGE_DIR);
  private file(key: string) {
    const p = path.resolve(this.root, key);
    if (!p.startsWith(this.root + path.sep)) throw new Error('Invalid storage key');
    return p;
  }
  private async target(key: string) {
    const p = this.file(key);
    await mkdir(path.dirname(p), { recursive: true, mode: DIR_MODE });
    return p;
  }
  async put(key: string, body: Buffer) {
    await writeFile(await this.target(key), body, { mode: FILE_MODE, flag: 'wx' });
  }
  async putFile(key: string, file: string) {
    const p = await this.target(key);
    try {
      await rename(file, p);
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EXDEV') throw e;
      await copyFile(file, p); // temp dir on another disk
      await rm(file, { force: true });
    }
    await chmod(p, FILE_MODE);
  }
  async stream(key: string) {
    const p = this.file(key);
    await stat(p); // a missing file fails here, before any response is sent
    return createReadStream(p);
  }
  async remove(key: string) { await rm(this.file(key), { force: true }); }
}

class S3Storage implements Storage {
  private client = new S3Client({
    region: config.S3_REGION || 'auto',
    endpoint: config.S3_ENDPOINT || undefined,
    forcePathStyle: !!config.S3_ENDPOINT,
    credentials: config.S3_ACCESS_KEY_ID ? { accessKeyId: config.S3_ACCESS_KEY_ID, secretAccessKey: config.S3_SECRET_ACCESS_KEY } : undefined,
  });
  async put(key: string, body: Buffer, contentType: string) {
    await this.client.send(new PutObjectCommand({ Bucket: config.S3_BUCKET, Key: key, Body: body, ContentType: contentType, ServerSideEncryption: 'AES256' }));
  }
  async putFile(key: string, file: string, contentType: string, size: number) {
    // Streamed from disk; the known length lets the SDK send it without buffering.
    await this.client.send(new PutObjectCommand({ Bucket: config.S3_BUCKET, Key: key, Body: createReadStream(file), ContentLength: size, ContentType: contentType, ServerSideEncryption: 'AES256' }));
    await rm(file, { force: true });
  }
  async stream(key: string) {
    const r = await this.client.send(new GetObjectCommand({ Bucket: config.S3_BUCKET, Key: key }));
    return r.Body as Readable;
  }
  async remove(key: string) { await this.client.send(new DeleteObjectCommand({ Bucket: config.S3_BUCKET, Key: key })); }
}

export const storage: Storage = config.STORAGE_DRIVER === 's3' ? new S3Storage() : new LocalStorage();
